#!/usr/bin/env python3
"""Test framework for long-term debt rules."""

import json
import re
from pathlib import Path

try:
    import tiktoken
    enc = tiktoken.get_encoding("cl100k_base")
    def count_tokens(text): return len(enc.encode(text))
except ImportError:
    def count_tokens(text): return len(text.split())

DOCS = [
    "BOEING_2019_10K",
    "ADOBE_2020_10K",
    "ACTIVISIONBLIZZARD_2020_10K",
    "COSTCO_2018_10K",
    "AMCOR_2019_10K",
    "AMAZON_2020_10K",
    "AMAZON_2019_10K",
    "ADOBE_2021_10K",
    "EBAY_2022_10K",
    "ADOBE_2019_10K",
    "AMCOR_2023Q2_10Q",
    "ADOBE_2022Q2_10Q",
    "ACTIVSIONBLIZZARD_2023Q2_10Q",
    "3M_2023Q2_10Q",
    "AMCOR_2022_8K_2022-07-01",
    "COSTCO_2023_8K_dated-2023-08-09",
    "COSTCO_2023_8K_dated-2023-08-16",
    "FOOTLOCKER_2022_8K_dated-2022-05-20",
]

QUESTION = "What is long-term debt at year-end (0 if none)?"

def load_labels():
    with open("data/financebench/sample_mix_doc_labels.json") as f:
        labels = json.load(f)
    result = {}
    for doc_name in DOCS:
        pdf_name = f"{doc_name}.pdf"
        if pdf_name in labels:
            result[doc_name] = labels[pdf_name].get(QUESTION)
    return result

def load_doc(doc_name):
    path = Path(f"data/financebench/processing/{doc_name}_reconstructed.json")
    if path.exists():
        with open(path) as f:
            return json.load(f)
    return None

def extract_numeric_value(answer):
    """Extract numeric value from answer for matching."""
    if answer is None or answer == "0":
        return None
    text = str(answer).replace(",", "").replace("$", "")
    match = re.search(r'([\d.]+)', text)
    if match:
        return match.group(1)
    return None

def check_hit(retrieved_text, answer):
    """Check if answer is found in retrieved text (substring match)."""
    if answer is None:
        return True  # null answer is always a "hit" (we just need relevant context)
    if answer == "0":
        return True  # 0 means no debt info needed, accepting any retrieval

    answer_lower = str(answer).lower()
    text_lower = retrieved_text.lower()

    # Check for exact substring
    if answer_lower in text_lower:
        return True

    # Check for numeric match
    numeric = extract_numeric_value(answer)
    if numeric and numeric in text_lower.replace(",", ""):
        return True

    # Special patterns
    # "$3.605 billion" -> "3,605" or "3.605"
    if "billion" in answer_lower:
        match = re.search(r'([\d.]+)\s*billion', answer_lower)
        if match:
            val = float(match.group(1))
            # Try finding as millions (3.605 billion = 3605 million)
            millions = int(val * 1000)
            if str(millions) in text_lower.replace(",", ""):
                return True
            # Try as decimal
            if f"{val:.3f}".replace(".", "") in text_lower.replace(",", "").replace(".", ""):
                return True

    return False

# Define rules to test
def rule_item8_financial_tables(doc):
    """Tables in Item 8 Financial Statements section."""
    try:
        return [s for s in doc.get("texts", [])
                if s.get("label") == "table" and
                any(kw in s.get("structure", {}).get("path_text", "").lower()
                    for kw in ["item 8", "item 6", "financial statements", "financial information"])]
    except Exception:
        return []

def rule_debt_keyword_tables(doc):
    """Tables containing 'debt' in text or path_text."""
    try:
        return [s for s in doc.get("texts", [])
                if s.get("label") == "table" and
                ("debt" in s.get("text", "").lower() or
                 "debt" in s.get("structure", {}).get("path_text", "").lower())]
    except Exception:
        return []

def rule_balance_sheet_tables(doc):
    """Balance sheet tables with debt or liabilities info."""
    try:
        results = []
        for s in doc.get("texts", []):
            if s.get("label") != "table":
                continue
            text = s.get("text", "").lower()
            path_text = s.get("structure", {}).get("path_text", "").lower()
            # Look for balance sheet markers
            if any(kw in text or kw in path_text for kw in [
                "balance sheet", "financial position",
                "long-term debt", "total debt", "long term debt"
            ]):
                results.append(s)
        return results
    except Exception:
        return []

def rule_part1_financial_tables(doc):
    """Part I financial tables for 10Q documents."""
    try:
        return [s for s in doc.get("texts", [])
                if s.get("label") == "table" and
                any(kw in s.get("structure", {}).get("path_text", "").lower()
                    for kw in ["part i", "condensed consolidated"])]
    except Exception:
        return []

def rule_8k_cover_page(doc):
    """Cover page for 8K documents to signal document type."""
    try:
        return [s for s in doc.get("texts", [])
                if s.get("page_no") == 1 and
                "8-k" in s.get("text", "").lower()]
    except Exception:
        return []

# Test function
def test_rules(rules, verbose=True):
    labels = load_labels()
    results = []

    for doc_name in DOCS:
        doc = load_doc(doc_name)
        if not doc:
            if verbose:
                print(f"SKIP: {doc_name} not found")
            continue

        answer = labels.get(doc_name)

        # Apply all rules and union results
        all_spans = []
        seen = set()
        for rule in rules:
            spans = rule(doc)
            for s in spans:
                span_id = id(s)
                if span_id not in seen:
                    seen.add(span_id)
                    all_spans.append(s)

        # Compute retrieved text
        retrieved_text = "\n".join(s.get("text", "") for s in all_spans)
        full_text = "\n".join(s.get("text", "") for s in doc.get("texts", []))

        # Compute cost
        ret_tokens = count_tokens(retrieved_text) if retrieved_text else 0
        full_tokens = count_tokens(full_text) if full_text else 1
        cost = ret_tokens / full_tokens if full_tokens > 0 else 0

        # Check hit
        hit = check_hit(retrieved_text, answer)

        results.append({
            "doc": doc_name,
            "answer": answer,
            "hit": hit,
            "cost": cost,
            "spans": len(all_spans),
            "ret_tokens": ret_tokens,
            "full_tokens": full_tokens
        })

        if verbose:
            status = "HIT" if hit else "MISS"
            print(f"{status}: {doc_name}, answer={answer}, spans={len(all_spans)}, cost={cost:.4f}")
            if not hit and answer and answer != "0":
                # Show what's missing
                numeric = extract_numeric_value(answer)
                print(f"  Looking for: {answer} (numeric: {numeric})")
                # Check first few tables
                for i, s in enumerate(all_spans[:3]):
                    print(f"  Span {i}: {s.get('text', '')[:100]}...")

    # Summary
    total = len(results)
    hits = sum(1 for r in results if r["hit"])
    avg_cost = sum(r["cost"] for r in results) / total if total > 0 else 0

def rule_table_long_term_debt_header(doc: dict) -> list[dict]:
    """Match tables with row headers containing 'long-term debt' or 'long-term obligations'."""
    try:
        results = []
        for span in doc.get("texts", []):
            if span.get("label") != "table":
                continue
            cells = span.get("table_data", {}).get("cells", [])
            row_headers = [c.get("text", "").lower() for c in cells if c.get("is_row_header")]
            for h in row_headers:
                if "long-term debt" in h or "long term debt" in h or "long-term obligations" in h:
                    results.append(span)
                    break
        return results
    except Exception:
        return []

def rule_total_obligations_tables(doc: dict) -> list[dict]:
    """Match tables containing 'total long-term obligations' keyword."""
    try:
        return [s for s in doc.get("texts", [])
                if s.get("label") == "table" and
                "long-term obligations" in s.get("text", "").lower()]
    except Exception:
        return []

def rule_selected_financial_data_table(doc: dict) -> list[dict]:
    """Tables whose immediate parent section is a Selected Financial Data heading."""
    try:
        out = []
        for sp in doc.get("texts", []):
            if sp.get("label") != "table":
                continue
            path = ((sp.get("structure") or {}).get("path_text") or "").lower()
            segs = [s.strip() for s in path.split("|")]
            if not segs:
                continue
            leaf = segs[-1]
            if (
                "selected financial data" in leaf
                or "selected consolidated financial data" in leaf
                or "five-year" in leaf
            ):
                out.append(sp)
        return out
    except Exception:
        return []

def rule_long_term_debt_tables(doc: dict) -> list[dict]:
    """Match tables containing 'long-term debt' or 'long term debt' keyword."""
    try:
        return [s for s in doc.get("texts", [])
                if s.get("label") == "table" and
                ("long-term debt" in s.get("text", "").lower() or
                 "long term debt" in s.get("text", "").lower())]
    except Exception:
        return []

def rule_debt_or_borrowings_note_table(doc: dict) -> list[dict]:
    """Tables under a Debt / Borrowings / Long-Term Debt note section."""
    try:
        import re
        out = []
        for sp in doc.get("texts", []):
            if sp.get("label") != "table":
                continue
            path = ((sp.get("structure") or {}).get("path_text") or "").lower()
            segs = [s.strip() for s in path.split("|")]
            ok = False
            for seg in segs:
                if re.search(r"^(?:note\s*)?\d+\.?\s*[-—–]?\s*(?:long[- ]term\s+)?(debt|borrowings)\b", seg):
                    ok = True
                    break
                if seg in {"debt", "borrowings", "long-term debt", "long term debt", "long-term borrowings"}:
                    ok = True
                    break
                if seg.endswith("long-term debt") or seg.endswith("long term debt"):
                    ok = True
                    break
            if ok:
                out.append(sp)
        return out
    except Exception:
        return []

    return coerced


def _span_key(span: dict[str, Any]) -> tuple[Any, ...]:
    return (
        span.get("page_no"),
        span.get("paragraph_no"),
        span.get("line_no"),
        span.get("text"),
    )


def _sort_key(span: dict[str, Any]) -> tuple[Any, ...]:
    return (
        span.get("page_no", 10**9),
        span.get("paragraph_no", 10**9),
        span.get("line_no", 10**9),
        span.get("text", ""),
    )


def _list_rule_files(rules_dir: Path, rule_names: list[str] | None = None) -> list[Path]:
    if rule_names:
        files = [rules_dir / f"{name}.py" for name in rule_names]
        return [path for path in files if path.exists()]
    return sorted(path for path in rules_dir.glob("rule_*.py") if path.is_file())


def _apply_rule_files(document: dict[str, Any], rule_files: list[Path]) -> dict[str, Any]:
    spans: list[dict[str, Any]] = []
    rules_applied: list[str] = []
    rules_no_hits: list[str] = []
    rule_errors: list[str] = []

    for rule_file in rule_files:
        rule_name = rule_file.stem
        try:
            rule_fn = _load_rule_fn(rule_file)
            raw_result = rule_fn(document)
        except Exception as exc:
            rule_errors.append(f"{rule_name}: {exc}")
            rules_no_hits.append(rule_name)
            continue

        if not isinstance(raw_result, list):
            rules_no_hits.append(rule_name)
            continue

        coerced = [_coerce_span(item) for item in raw_result]
        cleaned = [item for item in coerced if item]
        if cleaned:
            spans.extend(cleaned)
            rules_applied.append(rule_name)
        else:
            rules_no_hits.append(rule_name)

    deduped: list[dict[str, Any]] = []
    seen: set[tuple[Any, ...]] = set()
    for span in spans:
        key = _span_key(span)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(span)

    deduped.sort(key=_sort_key)
    retrieved_text = "\n\n".join(span["text"] for span in deduped) if deduped else ""

    return {
        "retrieved_spans": deduped,
        "retrieved_text": retrieved_text,
        "retrieved_token_count": _count_tokens(retrieved_text),
        "rules_applied": rules_applied,
        "rules_no_hits": rules_no_hits,
        "rule_errors": rule_errors,
    }


def _qa_call(question: str, retrieved_text: str, *, model_name: str = "gpt54") -> tuple[str | None, int, int, float]:
    model_mod = importlib.import_module(f"models.{model_name}")
    t0 = time.time()
    response = model_mod.client.chat.completions.create(
        model=model_mod.AZURE_DEPLOYMENT,
        messages=[
            {"role": "system", "content": _QA_SYSTEM},
            {"role": "user", "content": f"Passage:\n{retrieved_text}\n\nQuestion: {question}"},
        ],
        max_completion_tokens=500,
        temperature=0.0,
    )
    latency = round(time.time() - t0, 3)
    answer = (response.choices[0].message.content or "").strip() or None
    usage = response.usage
    return (
        answer,
        int(usage.prompt_tokens if usage else 0),
        int(usage.completion_tokens if usage else 0),
        latency,
    )


def _judge_call(
    dataset_name: str,
    question: str,
    ground_truth: Any,
    predicted: Any,
) -> tuple[bool, int, int]:
    if ground_truth is None or predicted is None:
        return False, 0, 0

    model_mod = importlib.import_module("models.gpt54")
    gt_str = json.dumps(ground_truth) if not isinstance(ground_truth, str) else ground_truth
    pred_str = str(predicted)
    response = model_mod.client.chat.completions.create(
        model=model_mod.AZURE_DEPLOYMENT,
        messages=[
            {
                "role": "system",
                "content": _JUDGE_SYSTEM_BY_DATASET.get(dataset_name, _JUDGE_SYSTEM_GENERIC),
            },
            {
                "role": "user",
                "content": f"Question: {question}\nGround Truth: {gt_str}\nPredicted: {pred_str}",
            },
        ],
        max_completion_tokens=10,
        temperature=0.0,
    )
    verdict = (response.choices[0].message.content or "").strip().lower()
    usage = response.usage
    return (
        verdict == "correct",
        int(usage.prompt_tokens if usage else 0),
        int(usage.completion_tokens if usage else 0),
    )


def _clean_stderr(stderr: str) -> str:
    lines = [
        line
        for line in stderr.splitlines()
        if line.strip() != "Reading additional input from stdin..."
    ]
    return "\n".join(lines).strip()[:4000]


def _parse_done_output(text: str) -> str | None:
    for line in text.splitlines():
        line = line.strip()
        if line.startswith("AGENTIC_RULE_FULL_DATA_DONE"):
            rest = line[len("AGENTIC_RULE_FULL_DATA_DONE") :].strip()
            if rest.startswith("report="):
                return rest[len("report=") :].strip()
    return None


def _parse_codex_events(jsonl_text: str) -> dict[str, Any]:
    usage_totals = {
        "input_tokens": 0,
        "output_tokens": 0,
        "cached_input_tokens": 0,
        "reasoning_output_tokens": 0,
    }
    thread_id: str | None = None
    error_message: str | None = None
    event_count = 0

    for raw_line in jsonl_text.splitlines():
        raw_line = raw_line.strip()
        if not raw_line:
            continue
        try:
            event = json.loads(raw_line)
        except json.JSONDecodeError:
            continue
        event_count += 1
        if event.get("type") == "thread.started":
            thread_id = event.get("thread_id")
        elif event.get("type") == "turn.completed":
            usage = event.get("usage") or {}
            for key in usage_totals:
                usage_totals[key] += int(usage.get(key) or 0)
        elif event.get("type") in {"error", "turn.failed"}:
            error_message = event.get("message") or str(event.get("error") or "")

    return {
        "usage_totals": usage_totals,
        "thread_id": thread_id,
        "error_message": error_message,
        "event_count": event_count,
    }


def _load_json(path: Path, default: Any) -> Any:
    if not path.exists():
        return default
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return default


def _write_json(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


def _relpath(path: Path) -> str:
    try:
        return str(path.relative_to(_ROOT))
    except ValueError:
        return str(path)


def _ledger_load(ledger_path: Path) -> dict[str, Any]:
    return _load_json(ledger_path, {"verify_accuracy_calls": []})


def _ledger_append_verify(ledger_path: Path, entry: dict[str, Any]) -> dict[str, Any]:
    ledger = _ledger_load(ledger_path)
    calls = ledger.setdefault("verify_accuracy_calls", [])
    calls.append(entry)
    _write_json(ledger_path, ledger)
    return ledger


def _manifest_docs(manifest: dict[str, Any]) -> dict[str, Path]:
    return {
        entry["doc_name"]: Path(entry["doc_path"])
        for entry in manifest.get("documents", [])
    }


def _manifest_ground_truth(manifest: dict[str, Any]) -> dict[str, Any]:
